// cmd/openapi dumps the OpenAPI 3.1 specification generated by huma from
// the typed handlers into packages/shared-types/openapi.yaml (F-13). CI
// verifies the committed file matches the code (anti-drift, acceptance #11).
//
// It builds the same router as the server, but with an in-memory ECDSA key
// and no real backends — handler registration only describes the API.
package main

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/rs/zerolog"

	"aps.local/apps/api/internal/audit"
	"aps.local/apps/api/internal/auth"
	"aps.local/apps/api/internal/httpapi"
	"aps.local/apps/api/internal/jwks"
	"aps.local/apps/api/internal/metrics"
	"aps.local/apps/api/internal/middleware"
)

func main() {
	out := flag.String("out", "../../packages/shared-types/openapi.yaml", "output file path")
	flag.Parse()

	// In-memory signing key: registration never signs anything.
	priv, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		fatal("key: %v", err)
	}
	keys, err := jwks.NewInMemory(priv, "openapi-export", "aps", "aps-clients")
	if err != nil {
		fatal("keystore: %v", err)
	}

	// Zero-dependency service: handlers only reference it while registering
	// the schema, never invoked during spec generation.
	met := metrics.New(nil)
	svc := auth.NewService(keys, nil, nil, nil, nil, audit.New(), met, auth.Options{
		Issuer:     "aps",
		Audience:   "aps-clients",
		AccessTTL:  15 * time.Minute,
		RefreshTTL: 7 * 24 * time.Hour,
	})

	realIP, err := middleware.NewRealIP(nil)
	if err != nil {
		fatal("realip: %v", err)
	}

	_, api := httpapi.NewRouter(httpapi.Deps{
		Svc:     svc,
		Keys:    keys,
		Logger:  zerolog.Nop(),
		Met:     met,
		RealIP:  realIP,
		Docs:    true,
		Version: "dev",
	})

	yamlBytes, err := api.OpenAPI().YAML()
	if err != nil {
		fatal("marshal yaml: %v", err)
	}
	if dir := filepath.Dir(*out); dir != "" && dir != "." {
		if err := os.MkdirAll(dir, 0o755); err != nil {
			fatal("mkdir: %v", err)
		}
	}
	if err := os.WriteFile(*out, yamlBytes, 0o644); err != nil {
		fatal("write %s: %v", err)
	}
	fmt.Printf("openapi.yaml written to %s\n", *out)
}

func fatal(format string, err error) {
	if err != nil {
		fmt.Fprintf(os.Stderr, format+"\n", err)
	} else {
		fmt.Fprintln(os.Stderr, format)
	}
	os.Exit(1)
}
